  "code": "public static int solve(int[] nums) {
    int triplets = 0, n = nums.length;
    int i = 0;
    while (i < n) {
        int j = i + 1;
        while (j < n) {
            int k = j + 1;
            while (k < n) {
                if (nums[i] * nums[j] == nums[k]) triplets++;
                k++;
            }
            j++;
        }
        i++;
    }
    return triplets;
}"
}

