    double r;
    Circle(double r) { this.r = r; }
    double area() { return Math.PI * r * r; }
}
public class Main {
    public static void main(String[] args) {
        Shape s = new Circle(2);
        s.describe();
    }
}", "expectedOutput": "Area: 12.566370614359172", "explanation": "describe() is a concrete method defined in the abstract class, but it calls area(), which is overridden by Circle -- dynamic dispatch means Circle's area() runs (pi * 2 * 2), printed via describe().", "difficulty": "medium", "questionFormat": "output_prediction"}

